/* @lc app=leetcode id=3887 lang=kotlin */ class Solution { fun find(p: IntArray, px: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> (path.size - 2 downTo 0).fold(0) { acc, i -> (acc xor px[path[i]]).also { px[path[i]] = it }.also { p[path[i]] = r } } } } fun numberOfEdgesAdded(n: Int, edges: Array<IntArray>): Int = IntArray(n) { it }.let { p -> IntArray(n).let { px -> edges.count { (u, v, w) -> find(p, px, u).let { ru -> find(p, px, v).let { rv -> if (ru == rv) (px[u] xor px[v]) == w else p.set(ru, rv).let { px[ru] = px[u] xor px[v] xor w }.let { true } } } } } } }